<template>
  <div class="pm-dashboard-layout"><AppSidebar :isOpen="sidebarOpen" @close="sidebarOpen=false"/><main class="pm-dashboard-main"><header class="pm-dashboard-topbar"><button class="pm-icon-btn pm-menu-btn" @click="sidebarOpen=!sidebarOpen">☰</button><div class="pm-topbar-search"><input v-model="filters.search" class="form-control" placeholder="Search..."></div></header><section class="pm-dashboard-content"><div class="container pm-ops-page incident-page">
    <div class="title-row"><h1>Incident Report <small v-if="mode==='list'">- Report List</small></h1><button v-if="mode==='form'" class="btn btn-outline-secondary" type="button" @click="mode='list'">List</button></div>
    <template v-if="mode==='list'"><section class="pm-card filter-card"><div class="filter-title">▽&nbsp; Filter</div><div class="filter-grid"><label>Report Number<input v-model="filters.report_no" class="form-control" placeholder="Select or enter report no."></label><label>Date From<input v-model="filters.date_from" class="form-control" type="date"></label><label>Date To<input v-model="filters.date_to" class="form-control" type="date"></label><label>Job Site / Customer<input v-model="filters.jobsite" class="form-control" placeholder="All"></label><label>Reported By (Staff)<input v-model="filters.reported_by" class="form-control" placeholder="All Staff"></label><label>Incident Type / Subject<input v-model="filters.incident_type" class="form-control" placeholder="All"></label><label>Status<select v-model="filters.status" class="form-control"><option value="">All</option><option value="open">Open</option><option value="under_review">Under Review</option><option value="closed">Closed</option></select></label><div class="filter-actions"><button class="btn btn-primary" type="button" @click="search">⌕ Search</button><button class="btn btn-outline-secondary" type="button" @click="clear">↻ Clear</button><button class="btn btn-outline-secondary" type="button" @click="exportCsv">⇩ Export</button></div></div></section>
    <section class="pm-card list-card"><div class="list-head"><div class="list-title">▣&nbsp; Incident Report List ({{ meta.total }})</div><div class="entries">Show <select v-model.number="filters.per_page" class="form-select" @change="search"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select> entries <button class="btn btn-primary" @click="create">＋ New Report</button></div></div><div class="table-responsive"><table class="table incident-table"><thead><tr><th>No.</th><th><button @click="sort('incident_no')">Report Number {{ mark('incident_no') }}</button></th><th><button @click="sort('occurred_at')">Date of Incident {{ mark('occurred_at') }}</button></th><th>Time of Incident</th><th>Job Site / Customer</th><th>Subject / Incident Title</th><th><button @click="sort('employee_name')">Reported By {{ mark('employee_name') }}</button></th><th>Reported To</th><th><button @click="sort('status')">Status {{ mark('status') }}</button></th><th>View Report</th></tr></thead><tbody><tr v-for="(item,index) in incidents" :key="item.id"><td>{{ (meta.from||1)+index }}</td><td>{{ item.incident_no }}</td><td>{{ date(item.occurred_at) }}</td><td>{{ time(item.occurred_at) }}</td><td>{{ item.jobsite||item.location||'—' }}</td><td>{{ item.incident_type||item.incident_description||'—' }}</td><td>{{ item.employee_name||'—' }}</td><td>{{ item.reported_to||'—' }}</td><td><span class="status" :class="`is-${item.status}`">{{ label(item.status) }}</span></td><td><button class="view" @click="edit(item.id)">◉ View Report</button></td></tr><tr v-if="!incidents.length"><td colspan="10" class="empty">No incident reports found.</td></tr></tbody></table></div><div class="pagination-bar"><span>Showing {{ meta.from||0 }} to {{ meta.to||0 }} of {{ meta.total }} entries</span><div class="pages"><button :disabled="meta.current_page<=1" @click="go(1)">First</button><button :disabled="meta.current_page<=1" @click="go(meta.current_page-1)">‹</button><button class="current">{{ meta.current_page }}</button><button :disabled="meta.current_page>=meta.last_page" @click="go(meta.current_page+1)">›</button><button :disabled="meta.current_page>=meta.last_page" @click="go(meta.last_page)">Last</button></div></div></section></template>
    <form v-else @submit.prevent="save"><section class="three-cards"><div class="pm-card"><h2><b>1</b> Report Info.</h2><div class="small-grid"><label>Report Number<input :value="form.incident_no||'Generated when saved'" class="form-control" disabled></label><label>Date of Incident<input v-model="form.occurred_date" type="date" class="form-control" required></label><label>Time of Incident<input v-model="form.occurred_time" type="time" class="form-control" required></label></div></div><div class="pm-card"><h2><b>2</b> Reported By</h2><div class="small-grid"><label>Name<input v-model="form.employee_name" class="form-control"></label><label>Position<input v-model="form.reporter_position" class="form-control"></label><label>Phone<input v-model="form.reporter_phone" class="form-control"></label><label>Email<input v-model="form.reporter_email" class="form-control"></label></div></div><div class="pm-card"><h2>Reported To</h2><div class="small-grid"><label>Name<input v-model="form.reported_to" class="form-control"></label><label>Position<input v-model="form.reported_to_position" class="form-control"></label><label>Phone<input v-model="form.reported_to_phone" class="form-control"></label><label>Email<input v-model="form.reported_to_email" class="form-control"></label></div></div></section><section class="pm-card subject"><h2><b>3</b> Subject / Incident Title</h2><input v-model="form.incident_type" class="form-control" placeholder="Slip and Fall Incident at Job Site"></section><section class="two-cards"><div class="pm-card"><h2><b>4</b> Incident Details</h2><div class="form-grid"><label>Job Site / Customer<input v-model="form.jobsite" class="form-control"></label><label>Address / Location<input v-model="form.location" class="form-control"></label><label>Exact Location<input v-model="form.incident_location" class="form-control"></label><label>Weather Conditions<input v-model="form.weather_conditions" class="form-control"></label><label class="wide">What Happened?<textarea v-model="form.incident_description" class="form-control" rows="4"></textarea></label></div></div><div class="pm-card"><h2><b>5</b> Incident Information</h2><div class="incident-info"><label>Any Damage to Property?<select v-model="form.damage_property" class="form-control"><option value="no">No</option><option value="yes">Yes</option></select></label><label>If Yes, Describe<input v-model="form.incident_damages" class="form-control"></label><label>Any Injury to Person?<select v-model="form.injury_person" class="form-control"><option value="no">No</option><option value="yes">Yes</option></select></label><label>If Yes, Describe Injury<input v-model="form.incident_injuries" class="form-control"></label><label>Police Called?<select v-model="form.police_called" class="form-control"><option :value="false">No</option><option :value="true">Yes</option></select></label><label>Police File No.<input v-model="form.police_file_no" class="form-control"></label></div></div></section><section class="two-cards"><div class="pm-card"><h2><b>6</b> Witnesses</h2><div class="witnesses"><div v-for="(row,index) in form.witness_people" :key="index"><input v-model="row.name" placeholder="Name"><input v-model="row.position" placeholder="Position / Company"><input v-model="row.phone" placeholder="Phone"><input v-model="row.email" placeholder="Email"><button type="button" @click="form.witness_people.splice(index,1)">×</button></div><button type="button" class="add" @click="form.witness_people.push({name:'',position:'',phone:'',email:''})">＋ Add Witness</button></div></div><div class="pm-card"><h2><b>7</b> Attachments</h2><p class="muted">Attachments can be added after the report is saved.</p></div></section><section class="pm-card"><h2><b>8</b> Additional Information</h2><div class="form-grid"><label>Actions Taken Immediately<input v-model="form.action_taken" class="form-control"></label><label>Recommendations to Prevent Recurrence<input v-model="form.actions_taken" class="form-control"></label><label>Other Contributing Factors<input v-model="form.description" class="form-control"></label><label>Notes<textarea v-model="form.incident_notes" class="form-control" rows="3"></textarea></label><label>Status<select v-model="form.status" class="form-control"><option value="open">Open</option><option value="under_review">Under Review</option><option value="closed">Closed</option></select></label></div></section><div class="actions"><button class="btn btn-outline-secondary" type="button" @click="mode='list'">List</button><button class="btn btn-outline-secondary" type="button" @click="reset">Reset</button><button class="btn btn-primary" :disabled="saving">{{ saving?'Saving…':'Save' }}</button><button v-if="form.id" class="btn btn-outline-danger" type="button" @click="remove">Delete</button><button class="btn btn-primary" type="button" :disabled="saving" @click="saveAndOut">Save & Out</button></div></form>
  </div></section></main></div>
</template>
<script setup>
import { reactive,ref,onMounted } from 'vue'; import AppSidebar from '../components/AppSidebar.vue'; import client from '../api/client';
const sidebarOpen=ref(false),mode=ref('list'),incidents=ref([]),saving=ref(false),meta=reactive({current_page:1,last_page:1,total:0,from:0,to:0}),today=new Date().toISOString().slice(0,10),filters=reactive({report_no:'',date_from:'',date_to:'',jobsite:'',reported_by:'',incident_type:'',status:'',search:'',sort_by:'occurred_at',sort_direction:'desc',per_page:10,page:1});
const blank=()=>({id:null,incident_no:'',occurred_date:today,occurred_time:'09:00',jobsite:'',location:'',incident_location:'',severity:'medium',employee_name:'',reporter_position:'',reporter_phone:'',reporter_email:'',reported_to:'',reported_to_position:'',reported_to_phone:'',reported_to_email:'',incident_type:'',incident_description:'',incident_damages:'',incident_injuries:'',damage_property:'no',injury_person:'no',police_called:false,police_file_no:'',weather_conditions:'',description:'',action_taken:'',actions_taken:'',incident_notes:'',witness_people:[],status:'open'}),form=reactive(blank());
const load=async()=>{const {data}=await client.get('/workforce/incident-reports',{params:filters});incidents.value=data.data||[];Object.assign(meta,data.meta||{})},search=()=>{filters.page=1;load()},clear=()=>{Object.assign(filters,{report_no:'',date_from:'',date_to:'',jobsite:'',reported_by:'',incident_type:'',status:'',search:'',sort_by:'occurred_at',sort_direction:'desc',per_page:10,page:1});load()},go=p=>{filters.page=p;load()},sort=k=>{filters.sort_direction=filters.sort_by===k&&filters.sort_direction==='asc'?'desc':'asc';filters.sort_by=k;search()},mark=k=>filters.sort_by===k?(filters.sort_direction==='asc'?'↑':'↓'):'';
const create=()=>{Object.assign(form,blank());mode.value='form'},edit=async id=>{const {data}=await client.get(`/workforce/incident-reports/${id}`),item=data.data;const occurred=new Date(item.occurred_at);Object.assign(form,blank(),item,{occurred_date:item.occurred_at?.slice(0,10)||today,occurred_time:item.occurred_at?.slice(11,16)||'09:00',witness_people:item.witness_people||[]});mode.value='form'},reset=()=>Object.assign(form,blank()),payload=()=>({...form,occurred_at:`${form.occurred_date} ${form.occurred_time}:00`}),save=async()=>{saving.value=true;try{const data=payload();form.id?await client.put(`/workforce/incident-reports/${form.id}`,data):await client.post('/workforce/incident-reports',data);await load();mode.value='list'}finally{saving.value=false}},saveAndOut=save,remove=async()=>{if(!confirm('Delete this incident report?'))return;await client.delete(`/workforce/incident-reports/${form.id}`);await load();mode.value='list'},date=v=>v?new Date(v).toLocaleDateString():'—',time=v=>v?new Date(v).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'—',label=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const exportCsv=()=>{const rows=[['Report Number','Date','Job Site','Subject','Reported By','Status'],...incidents.value.map(i=>[i.incident_no,i.occurred_at,i.jobsite,i.incident_type,i.employee_name,i.status])],blob=new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='incident-reports.csv';a.click();URL.revokeObjectURL(a.href)};onMounted(load);
</script>
