e{grid-column:1/-1}.witnesses>div{display:grid;grid-template-columns:1fr 1fr 1fr 1fr auto;gap:.35rem;margin-bottom:.4rem}.witnesses input{min-width:0;border:1px solid #d7dee9;padding:.35rem}.witnesses button{border:0;background:none;color:#b42318}.witnesses .add{color:#062a80;font-weight:700}.muted{color:#667085;font-size:.85rem}.actions{display:flex;justify-content:flex-end;gap:.7rem}.btn{font-weight:700;min-height:38px}@media(max-width:900px){.filter-grid,.form-grid,.three-cards,.two-cards{grid-template-columns:1fr 1fr}.incident-info{grid-template-columns:1fr 1fr}}@media(max-width:600px){.filter-grid,.form-grid,.small-grid,.incident-info,.three-cards,.two-cards{grid-template-columns:1fr}.title-row,.list-head,.pagination-bar{align-items:flex-start;flex-direction:column}.subject{display:block}.subject h2{margin-bottom:.7rem}.witnesses>div{grid-template-columns:1fr}.actions{flex-wrap:wrap}}
